get_shipping_settings.code:
var response = await client.ShippingSettings.GetShippingSettingsAsync();
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var shippingSettings = (IReadOnlyDictionary<string, object?>)body["shipping_settings"]!;
Console.WriteLine($"{shippingSettings["apply_store_tax_settings_to_shipping"]} {shippingSettings["enable_shipping_class"]}");

patch_shipping_settings.code:
var response = await client.ShippingSettings.PatchShippingSettingsAsync(new Dictionary<string, object?>
{
    ["shipping_settings"] = new Dictionary<string, object?> { ["apply_store_tax_settings_to_shipping"] = true },
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var shippingSettings = (IReadOnlyDictionary<string, object?>)body["shipping_settings"]!;
Console.WriteLine(shippingSettings["apply_store_tax_settings_to_shipping"]);
